	rm -rf $(BUILD_DIR)
	rm -rf $(VENV_DIR)
	@echo "✓ 清理完成"

# ==================== 开发模式 ====================

dev: install-deps
	@echo "进入开发模式..."
	$(MAKE) -C $(VENV_DIR) pip install -r ../requirements.txt
	$(MAKE) compile-py
	$(MAKE) compile-c
	@echo "开发环境就绪，可运行:"
	@echo "  make run-c"
	@echo "  make run-py"
EOF

