        print(f"[cron-doctor] 检查失败：{e}")
        return False

def check_crontab():
    """检查 crontab 语法"""
    print("[cron-doctor] 检查 crontab 语法...")
    try:
        result = subprocess.run(['crontab', '-l'], capture_output=True, text=True)
        if result.returncode != 0:
            print("[cron-doctor] WARNING: 未找到 crontab")
