                    print(f"  行 {i+1}: {line}")
            return True
    except Exception as e:
        print(f"[cron-doctor] 检查失败：{e}")
        return False

def check_scripts():
    """检查脚本文件"""
    print("[cron-doctor] 检查脚本文件...")
    scripts_dir = '/home/user/devops/scripts'
    if os.path.exists(scripts_dir):
        for f in os.listdir(scripts_dir):
            filepath = os.path.join(scripts_dir, f)
            if os.path.isfile(filepath):
                print(f"  找到脚本：{f}")
                # 检查脚本权限
                mode = os.stat(filepath).st_mode
                if mode & 0o111:
                    print(f"    权限 OK (可执行)")
                else:
                    print(f"    WARNING: 脚本不可执行")
    else:
        print("  WARNING: scripts 目录不存在")

